CREATE TABLE users (id BIGINT AUTO_INCREMENT PRIMARY KEY, username VARCHAR(255) NOT NULL UNIQUE, password_hash VARCHAR(255) NOT NULL);
CREATE TABLE devices (id BIGINT AUTO_INCREMENT PRIMARY KEY, device_id VARCHAR(255) NOT NULL UNIQUE, name VARCHAR(255) NOT NULL, owner_id BIGINT NOT NULL, key_hash VARCHAR(255) NOT NULL, last_seen TIMESTAMP(6), simulated BOOLEAN NOT NULL DEFAULT FALSE, connected BOOLEAN NOT NULL DEFAULT FALSE, min_bpm DOUBLE NOT NULL DEFAULT 45, max_bpm DOUBLE NOT NULL DEFAULT 130, min_spo2 DOUBLE NOT NULL DEFAULT 92, FOREIGN KEY(owner_id) REFERENCES users(id));
CREATE TABLE readings (id BIGINT AUTO_INCREMENT PRIMARY KEY, device_id BIGINT NOT NULL, boot_id VARCHAR(255) NOT NULL, sequence_no BIGINT NOT NULL, received_at TIMESTAMP(6) NOT NULL, captured_at TIMESTAMP(6), simulated BOOLEAN NOT NULL, FOREIGN KEY(device_id) REFERENCES devices(id), CONSTRAINT uq_packet UNIQUE(device_id,boot_id,sequence_no), CHECK(sequence_no>=0));
CREATE INDEX ix_readings_device_time ON readings(device_id,received_at);
CREATE TABLE health_readings (id BIGINT AUTO_INCREMENT PRIMARY KEY, reading_id BIGINT NOT NULL UNIQUE, bpm DOUBLE, spo2 DOUBLE, finger_present BOOLEAN NOT NULL, quality VARCHAR(255) NOT NULL, FOREIGN KEY(reading_id) REFERENCES readings(id), CHECK(bpm IS NULL OR bpm BETWEEN 20 AND 250), CHECK(spo2 IS NULL OR spo2 BETWEEN 0 AND 100));
CREATE TABLE motion_readings (id BIGINT AUTO_INCREMENT PRIMARY KEY, reading_id BIGINT NOT NULL UNIQUE, ax DOUBLE, ay DOUBLE, az DOUBLE, gx DOUBLE, gy DOUBLE, gz DOUBLE, tilt DOUBLE, possible_fall BOOLEAN NOT NULL, activity VARCHAR(255) NOT NULL, FOREIGN KEY(reading_id) REFERENCES readings(id));
CREATE TABLE gps_locations (id BIGINT AUTO_INCREMENT PRIMARY KEY, reading_id BIGINT NOT NULL UNIQUE, latitude DOUBLE, longitude DOUBLE, speed DOUBLE, satellites INTEGER, fix BOOLEAN NOT NULL, gps_time TIMESTAMP(6), FOREIGN KEY(reading_id) REFERENCES readings(id), CHECK(latitude IS NULL OR latitude BETWEEN -90 AND 90), CHECK(longitude IS NULL OR longitude BETWEEN -180 AND 180));
CREATE TABLE alerts (id BIGINT AUTO_INCREMENT PRIMARY KEY, device_id BIGINT NOT NULL, type VARCHAR(255) NOT NULL, severity VARCHAR(255) NOT NULL, message VARCHAR(255) NOT NULL, created_at TIMESTAMP(6) NOT NULL, acknowledged_at TIMESTAMP(6), acknowledged_by BIGINT, FOREIGN KEY(device_id) REFERENCES devices(id), FOREIGN KEY(acknowledged_by) REFERENCES users(id));
CREATE INDEX ix_alerts_device_time ON alerts(device_id,created_at);
CREATE TABLE device_connections (id BIGINT AUTO_INCREMENT PRIMARY KEY, device_id BIGINT NOT NULL, connected BOOLEAN NOT NULL, occurred_at TIMESTAMP(6) NOT NULL, FOREIGN KEY(device_id) REFERENCES devices(id));
CREATE INDEX ix_connection_device_time ON device_connections(device_id,occurred_at);
